import type { ProjectProperties } from '@/lib/models';
import { db } from '@/db';
import { projects } from '@/db/schema';
import { eq, desc } from 'drizzle-orm';

/**
 * Saves a project to PostgreSQL. If the project has an ID, it updates it.
 * Otherwise, it creates a new document.
 * @param projectData The project data to save.
 * @returns The saved project data with a confirmed ID and updated timestamp.
 */
export async function saveProject(projectData: ProjectProperties): Promise<ProjectProperties> {
  const now = new Date().toISOString();

  // Extract userId from meta.author (needs to be numeric for FK)
  const userId = projectData.meta?.author 
    ? parseInt(projectData.meta.author, 10)
    : null;

  if (!userId) {
    throw new Error('Project must have a valid userId (meta.author)');
  }

  const projectData_normalized = {
    userId,
    title: projectData.title || 'Untitled Project',
    description: projectData.description || null,
    content: projectData.content || null,
    status: projectData.status || 'draft',
    language: projectData.language || 'en',
    templateId: projectData.templateId ? parseInt(projectData.templateId as any, 10) : null,
    lastModifiedBy: projectData.meta?.author ? parseInt(projectData.meta.author, 10) : null,
    metadata: {
      ...projectData.meta,
      updated: now,
    },
  };

  if (projectData.id) {
    // Update existing project
    const projectId = parseInt(projectData.id as any, 10);
    await db
      .update(projects)
      .set({
        ...projectData_normalized,
        updatedAt: new Date(now),
      })
      .where(eq(projects.id, projectId));

    return {
      ...projectData,
      meta: {
        ...projectData.meta,
        updated: now,
      },
    };
  } else {
    // Create new project
    const result = await db
      .insert(projects)
      .values({
        ...projectData_normalized,
        createdAt: new Date(now),
        updatedAt: new Date(now),
      })
      .returning();

    return {
      ...projectData,
      id: result[0]?.id?.toString(),
      meta: {
        ...projectData.meta,
        updated: now,
      },
    };
  }
}

/**
 * Fetches all projects for a given user.
 * @param userId The ID of the user whose projects to fetch.
 * @returns An array of project properties.
 */
export async function getProjects(userId: string): Promise<ProjectProperties[]> {
  const numUserId = parseInt(userId, 10);

  const result = await db
    .select()
    .from(projects)
    .where(eq(projects.userId, numUserId))
    .orderBy(desc(projects.updatedAt));

  return result.map(proj => ({
    id: proj.id?.toString(),
    title: proj.title,
    description: proj.description || undefined,
    content: proj.content || undefined,
    status: proj.status as any,
    language: proj.language,
    templateId: proj.templateId?.toString(),
    meta: {
      author: proj.userId?.toString(),
      updated: proj.updatedAt?.toISOString(),
      ...(proj.metadata || {}),
    },
  } as ProjectProperties));
}

/**
 * Fetches a single project by its ID.
 * @param projectId The ID of the project to fetch.
 * @returns The project properties or null if not found.
 */
export async function getProject(projectId: string): Promise<ProjectProperties | null> {
  const numProjectId = parseInt(projectId, 10);

  const result = await db
    .select()
    .from(projects)
    .where(eq(projects.id, numProjectId))
    .limit(1);

  if (result.length === 0) {
    return null;
  }

  const proj = result[0];
  return {
    id: proj.id?.toString(),
    title: proj.title,
    description: proj.description || undefined,
    content: proj.content || undefined,
    status: proj.status as any,
    language: proj.language,
    templateId: proj.templateId?.toString(),
    meta: {
      author: proj.userId?.toString(),
      updated: proj.updatedAt?.toISOString(),
      ...(proj.metadata || {}),
    },
  } as ProjectProperties;
}

/**
 * Deletes a project from PostgreSQL.
 * @param projectId The ID of the project to delete.
 */
export async function deleteProject(projectId: string): Promise<void> {
  const numProjectId = parseInt(projectId, 10);
  await db
    .delete(projects)
    .where(eq(projects.id, numProjectId));
}"}

