}", "replace": "'use server';

import type { TransactionProperties } from '@/lib/models';
import { db } from '@/db';
import { transactions } from '@/db/schema';
import { eq, desc, and, gte, lte, gt } from 'drizzle-orm';

export async function createTransaction(data: Omit<TransactionProperties, 'createdAt' | 'id'>) {
    const userId = typeof data.userId === 'string' ? parseInt(data.userId, 10) : data.userId;

    const result = await db
        .insert(transactions)
        .values({
            userId,
            type: data.type || 'purchase',
            amount: data.amount ? parseFloat(data.amount.toString()) : null,
            credits: data.credits || null,
            description: data.description || null,
            status: data.status || 'completed',
            createdAt: new Date(),
        })
        .returning();

    return { id: result[0]?.id?.toString() };
}

export async function getTransactionsByStatus({ 
    status, 
    limit, 
    lastVisibleId 
}: { 
    status: 'pending' | 'verified' | 'rejected' | 'completed', 
    limit: number, 
    lastVisibleId?: string 
}): Promise<{ 
    transactions: TransactionProperties[], 
    hasNextPage: boolean, 
    lastVisibleId?: string | null 
}> {
    let query = db
        .select()
        .from(transactions)
        .where(eq(transactions.status, status))
        .orderBy(desc(transactions.createdAt))
        .limit(limit + 1);

    // Handle pagination with lastVisibleId
    if (lastVisibleId) {
        const lastId = parseInt(lastVisibleId, 10);
        query = query.where(gt(transactions.id, lastId));
    }

    const result = await query;

    const txns = result.slice(0, limit).map(doc => ({
        id: doc.id?.toString(),
        userId: doc.userId?.toString(),
        type: doc.type,
        amount: doc.amount?.toString(),
        credits: doc.credits,
        description: doc.description,
        status: doc.status,
        createdAt: doc.createdAt?.toISOString(),
    } as TransactionProperties));

    const hasNextPage = result.length > limit;
    const newLastVisibleId = hasNextPage ? txns[txns.length - 1].id : null;

    return { transactions: txns, hasNextPage, lastVisibleId: newLastVisibleId };
}

export async function getTransactionsByUserId(userId: string): Promise<TransactionProperties[]> {
    const numUserId = parseInt(userId, 10);

    const result = await db
        .select()
        .from(transactions)
        .where(eq(transactions.userId, numUserId))
        .orderBy(desc(transactions.createdAt));

    return result.map(doc => ({
        id: doc.id?.toString(),
        userId: doc.userId?.toString(),
        type: doc.type,
        amount: doc.amount?.toString(),
        credits: doc.credits,
        description: doc.description,
        status: doc.status,
        createdAt: doc.createdAt?.toISOString(),
    } as TransactionProperties));
}

export async function getTransactionsByDateRange(startDate: string, endDate: string): Promise<TransactionProperties[]> {
    const startDateTime = new Date(startDate);
    const endDateTime = new Date(endDate);

    const result = await db
        .select()
        .from(transactions)
        .where(
            and(
                gte(transactions.createdAt, startDateTime),
                lte(transactions.createdAt, endDateTime)
            )
        )
        .orderBy(desc(transactions.createdAt));

    return result.map(doc => ({
        id: doc.id?.toString(),
        userId: doc.userId?.toString(),
        type: doc.type,
        amount: doc.amount?.toString(),
        credits: doc.credits,
        description: doc.description,
        status: doc.status,
        createdAt: doc.createdAt?.toISOString(),
    } as TransactionProperties));
}"}

