import { db } from '@/db';
import { generation_history } from '@/db/schema';

interface GenerationLog {
    agentId: string;
    userId: string;
    input: any;
    output: any;
    creditCost: number;
    createdAt: string; // ISO string
}

/**
 * Logs a successful AI agent generation to PostgreSQL.
 * This creates a knowledge base of all agent activities.
 * @param logData - The data to be logged.
 */
export async function logGeneration(logData: Omit<GenerationLog, 'createdAt'>): Promise<void> {
    try {
        const userId = typeof logData.userId === 'string' 
            ? parseInt(logData.userId, 10) 
            : logData.userId;

        await db
            .insert(generation_history)
            .values({
