'use server';


export async function createGenerativeTemplate(templateType: 'docx' | 'pptx', id: string, data: any) {
  const collectionRef = adminDb.collection('templates').doc(templateType).collection('styles');
  const docRef = collectionRef.doc(id);
  const doc = await docRef.get();

  if (doc.exists) {
    throw new Error(`A ${templateType} template with this ID already exists.`);
  }

  await docRef.set({ ...data, id, createdAt: new Date().toISOString() });
  return { id, ...data };
}

// You can add more template-related server functions here in the future.", "replace": "'use server';

import { db } from '@/db';
import { templates } from '@/db/schema';
import { eq, and } from 'drizzle-orm';

export async function createGenerativeTemplate(templateType: 'docx' | 'pptx', id: string, data: any) {
  // Check if template already exists
  const existing = await db
    .select()
    .from(templates)
    .where(
      and(
        eq(templates.type, templateType),
        eq(templates.name, id)
      )
    )
    .limit(1);

  if (existing.length > 0) {
    throw new Error(`A ${templateType} template with this ID already exists.`);
  }

  // Create new template
  const result = await db
    .insert(templates)
    .values({
      name: id,
      type: templateType,
      description: data.description || null,
      category: data.category || null,
      sections: data.sections || null,
      createdAt: new Date(),
      updatedAt: new Date(),
    })
    .returning();

  return {
    id: result[0]?.id?.toString(),
    name: result[0]?.name,
    type: result[0]?.type,
    ...data,
    createdAt: result[0]?.createdAt?.toISOString(),
  };
}

// You can add more template-related server functions here in the future."}

